import { expect, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const DAY_MS = 24 * 60 * 60 * 1000;

function isoDateInDays(days: number): string {
  return new Date(Date.now() + days * DAY_MS).toISOString().slice(0, 10);
}

async function createVendor(api: APIRequestContext): Promise<string> {
  const suffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
  const res = await api.post("/api/vendors", {
    data: {
      name: uniqueName("Rev08 Vendor"),
      category: "services",
      contact_email: `ops+${suffix}@example.com`,
    },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()).id as string;
}

async function uploadInsurance(api: APIRequestContext, vendorId: string, expiry: string): Promise<string> {
  const body = `CERTIFICATE OF INSURANCE\nPolicy number: POL-${Date.now().toString(36)}\nPolicy expires: ${expiry}\nExpiration date: ${expiry}\nExpiry: ${expiry}\nValid through: ${expiry}\n`;
  const res = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance.txt",
        mimeType: "text/plain",
        buffer: Buffer.from(body, "utf-8"),
      },
    },
  });
  expect(res.status(), await res.text()).toBe(201);
  return (await res.json()).id as string;
}

const examples = [
  { days: 0, include: true },
  { days: 30, include: true },
  { days: 31, include: false },
];

for (const { days, include } of examples) {
  test(
    `insurance expiring in ${days} days ${include ? "is" : "is not"} flagged insurance_expiring_soon`,
    { tag: "@REV-08" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorId = await createVendor(member);
      const documentId = await uploadInsurance(member, vendorId, isoDateInDays(days));

      // Wait for background extraction to finish before reading flags.
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${documentId}`);
            expect(res.status(), await res.text()).toBe(200);
            return (await res.json()).status as string;
          },
          { timeout: 60_000 },
        )
        .toBe("extracted");

      const extractionRes = await member.get(`/api/documents/${documentId}/extraction`);
      expect(extractionRes.status(), await extractionRes.text()).toBe(200);
      const extraction = await extractionRes.text();

      // Act
      const res = await member.get(`/api/vendors/${vendorId}`);

      // Assert
      expect(res.status(), await res.text()).toBe(200);
      const vendor = await res.json();
      const context = `vendor=${JSON.stringify(vendor)} extraction=${extraction}`;
      if (include) {
        expect(vendor.flags, context).toContain("insurance_expiring_soon");
      } else {
        expect(vendor.flags, context).not.toContain("insurance_expiring_soon");
      }
    },
  );
}
